#[test]
fn language_attrs_static_inline() {
    let r = parse_c("static inline int* f(const int* p, ...) { return 0; }");
    // Verify JSON: is_static, is_inline, returns_ptr, takes_ptr, is_variadic, has_const, returns_void=false
